// The referee. Every client request comes here: verify the caller, parse the request,
// run it through the shared engine via @tenfold/server, and save atomically.
// `_shared/` is generated by `npm run functions:sync` from packages/engine and packages/server.
import { createClient } from '@supabase/supabase-js';
import { createLocalJWKSet, jwtVerify, type JSONWebKeySet } from 'jose';
import bundledKeys from '../_shared/jwks.json' with { type: 'json' };
import { handle, handsOf, parseAction, type Store, type StoredRoom } from '@tenfold/server';

const url = Deno.env.get('SUPABASE_URL');
const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
if (!url || !serviceKey) throw new Error('Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY');

const admin = createClient(url, serviceKey, { auth: { persistSession: false } });

// Session tokens are checked against the signing keys bundled at deploy time, so a cold
// start does not have to download them. If the keys have rotated since the deploy,
// Supabase's own check (which fetches the current keys) takes over.
const localKeys = createLocalJWKSet(bundledKeys as JSONWebKeySet);
const verifySession = async (token: string): Promise<string | undefined> => {
  try {
    const { payload } = await jwtVerify(token, localKeys, { issuer: `${url}/auth/v1` });
    return payload.role === 'authenticated' && typeof payload.sub === 'string' ? payload.sub : undefined;
  } catch {
    const { data } = await admin.auth.getClaims(token);
    return data?.claims.role === 'authenticated' ? data.claims.sub : undefined;
  }
};

const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-region',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...cors, 'Content-Type': 'application/json' } });

const store: Store = {
  loadRoom: async (key) => {
    // One round trip: the room plus its seats, embedded through the foreign key.
    const query = admin.from('rooms').select('id, code, version, data, game, room_players(player_id, user_id)');
    const { data: room, error } = await ('id' in key ? query.eq('id', key.id) : query.eq('code', key.code)).maybeSingle();
    if (error) throw error;
    if (!room) return null;
    const { room_players: members, ...rest } = room as typeof room & {
      room_players: { player_id: string; user_id: string }[];
    };
    return {
      ...rest,
      members: members.map((m) => ({ playerId: m.player_id, userId: m.user_id })),
    } as StoredRoom;
  },
  createRoom: async (room) => {
    const { data, error } = await admin.rpc('create_room', {
      p_id: room.id,
      p_code: room.code,
      p_data: room.data,
      p_members: room.members,
    });
    if (error) throw error;
    return data === true;
  },
  saveRoom: async (room, expectedVersion) => {
    const { data, error } = await admin.rpc('commit_room', {
      p_id: room.id,
      p_expected_version: expectedVersion,
      p_data: room.data,
      p_game: room.game,
      p_members: room.members,
      p_hands: room.game ? handsOf(room) : [],
    });
    if (error) throw error;
    return data === true;
  },
};

const deps = {
  random: () => crypto.getRandomValues(new Uint32Array(1))[0] / 0x100000000,
  newId: () => crypto.randomUUID(),
  now: () => Date.now(),
};

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  if (req.method !== 'POST') return json({ ok: false, error: { code: 'bad-request' } }, 405);

  const token = req.headers.get('Authorization')?.replace(/^Bearer\s+/i, '');
  const userId = token ? await verifySession(token) : undefined;
  if (!userId) return json({ ok: false, error: { code: 'unauthorized' } }, 401);

  const action = parseAction(await req.json().catch(() => null));
  if (!action) return json({ ok: false, error: { code: 'bad-request' } }, 400);

  try {
    return json(await handle(store, deps, userId, action));
  } catch (error) {
    console.error(error);
    return json({ ok: false, error: { code: 'server-error' } }, 500);
  }
});
